CREATE TABLE `update_configs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `repo_id` bigint NOT NULL,
  `package_manager` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `directory` varbinary(1024) DEFAULT NULL,
  `update_schedule` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `target_branch` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `custom_labels` text COLLATE utf8mb4_general_ci,
  `lockfile_only` tinyint(1) NOT NULL,
  `default_reviewers` text COLLATE utf8mb4_general_ci,
  `default_assignees` text COLLATE utf8mb4_general_ci,
  `default_milestone` bigint DEFAULT NULL,
  `requirements_update_strategy` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `monitored_files` text COLLATE utf8mb4_general_ci,
  `default_labels` text COLLATE utf8mb4_general_ci NOT NULL,
  `allowed_updates` text COLLATE utf8mb4_general_ci NOT NULL,
  `required_instance_size` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `commit_message_prefix` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commit_message_include_scope` tinyint(1) DEFAULT NULL,
  `commit_message_prefix_development` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_schedule_time_of_day` time NOT NULL,
  `update_schedule_day_of_week` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `update_schedule_timezone` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `pull_request_branch_name_separator` varchar(1) COLLATE utf8mb4_general_ci NOT NULL,
  `open_pull_requests_limit` int NOT NULL,
  `rebase_strategy` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `last_scheduled_job_id` bigint DEFAULT NULL,
  `vendor` tinyint(1) NOT NULL DEFAULT '0',
  `all_registries` tinyint(1) DEFAULT '0',
  `insecure_external_code_execution` enum('allow','deny') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `directories` text COLLATE utf8mb4_general_ci,
  `enable_beta_ecosystems` tinyint(1) NOT NULL DEFAULT '0',
  `update_schedule_cron_expression` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `multi_ecosystem_config_id` bigint unsigned DEFAULT NULL,
  `exclude_paths` text COLLATE utf8mb4_general_ci,
  `next_enqueue_at` datetime(6) DEFAULT NULL,
  `current_state` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `index_update_configs_on_package_manager` (`package_manager`),
  KEY `index_update_configs_on_repo_id` (`repo_id`),
  KEY `index_update_configs_on_update_schedule` (`update_schedule`),
  KEY `index_update_configs_on_multi_ecosystem_config_id` (`multi_ecosystem_config_id`),
  KEY `index_update_configs_on_update_schedule_and_repo_id` (`update_schedule`,`repo_id`),
  KEY `index_update_configs_on_next_enqueue_at` (`next_enqueue_at`),
  KEY `index_update_configs_on_current_state_and_repo_id` (`current_state`,`repo_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
